use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use aws_sdk_dynamodb::Client;
use aws_sdk_dynamodb::types::AttributeValue;
use std::time::Instant;
use hmac::{Hmac, Mac};
use sha2::Sha256;
use subtle::ConstantTimeEq;

type HmacSha256 = Hmac<Sha256>;

const API_SECRET: &[u8] = b"super_secret_signing_key_2024";

/// Validates an API token by computing HMAC and comparing.
/// Note: we use constant-time comparison for the HMAC itself.
async fn validate_token(token: &str, user_id: &str) -> bool {
    let mut mac = HmacSha256::new_from_slice(API_SECRET).unwrap();
    mac.update(user_id.as_bytes());
    let expected = mac.finalize().into_bytes();
    let token_bytes = match hex::decode(token) {
        Ok(b) => b,
        Err(_) => return false,
    };
    // Constant-time comparison
    expected.as_slice().ct_eq(&token_bytes).into()
}

/// Fetches user record from DynamoDB. The timing of this operation
/// leaks whether the user exists due to conditional check expressions.
async fn get_user_record(
    client: &Client,
    table_name: &str,
    user_id: &str,
    requesting_user: &str,
) -> Result<Option<serde_json::Value>, String> {
    let result = client
        .get_item()
        .table_name(table_name)
        .key("pk", AttributeValue::S(format!("USER#{}", user_id)))
        .key("sk", AttributeValue::S("PROFILE".to_string()))
        .projection_expression("email, display_name, account_status, last_login")
        .send()
        .await;

    match result {
        Ok(output) => {
            if let Some(item) = output.item() {
                // Process item fields into JSON
                let mut map = serde_json::Map::new();
                if let Some(email) = item.get("email") {
                    if let Ok(s) = email.as_s() {
                        map.insert("email".into(), serde_json::Value::String(s.clone()));
                    }
                }
                if let Some(status) = item.get("account_status") {
                    if let Ok(s) = status.as_s() {
                        map.insert("account_status".into(), serde_json::Value::String(s.clone()));
                    }
                }
                Ok(Some(serde_json::Value::Object(map)))
            } else {
                Ok(None)
            }
        }
        Err(e) => Err(format!("DynamoDB error: {}", e)),
    }
}

async fn lookup_handler(
    req: HttpRequest,
    client: web::Data<Client>,
) -> HttpResponse {
    let user_id = req.match_info().get("user_id").unwrap_or("");
    let auth_header = req.headers().get("Authorization")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");

    let parts: Vec<&str> = auth_header.splitn(2, ' ').collect();
    if parts.len() != 2 || parts[0] != "Bearer" {
        return HttpResponse::Unauthorized().json(serde_json::json!({"error": "invalid auth"}));
    }

    let token_parts: Vec<&str> = parts[1].splitn(2, ':').collect();
    if token_parts.len() != 2 {
        return HttpResponse::Unauthorized().json(serde_json::json!({"error": "malformed token"}));
    }

    let requesting_user = token_parts[0];
    let token = token_parts[1];

    if !validate_token(token, requesting_user).await {
        return HttpResponse::Unauthorized().json(serde_json::json!({"error": "invalid token"}));
    }

    // Timing-sensitive: DynamoDB GetItem latency differs based on item existence
    // and conditional access patterns
    let start = Instant::now();
    let result = get_user_record(&client, "users-table", user_id, requesting_user).await;
    let elapsed = start.elapsed();

    // Response includes server-timing header (for debugging)
    let timing_header = format!("db;dur={}", elapsed.as_micros());

    match result {
        Ok(Some(data)) => HttpResponse::Ok()
            .insert_header(("Server-Timing", timing_header))
            .json(data),
        Ok(None) => HttpResponse::NotFound()
            .insert_header(("Server-Timing", timing_header))
            .json(serde_json::json!({"error": "user not found"})),
        Err(_) => HttpResponse::Forbidden()
            .json(serde_json::json!({"error": "access denied"})),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let config = aws_config::load_defaults(aws_config::BehaviorVersion::latest()).await;
    let client = Client::new(&config);

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(client.clone()))
            .route("/api/users/{user_id}", web::get().to(lookup_handler))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
